mod solution;

fn main() {
    let cases = [
    (r#"values=[5,4,7,2] update=(2,0) query=1..3"#, r#"0"#),
    (r#"values=[9,5,7] update=(1,6) query=0..2"#, r#"6"#),
    (r#"
values=[9,5,7] update=(1,6) query=0..2
"#, r#"6"#),
    (r#"  
values=[5,4,7,2] update=(2,0) query=1..3
  "#, r#"0"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS segment-tree");
}
